export function ImageSearch() {
  var queryState = useState('');
  var query = queryState[0];
  var setQuery = queryState[1];

  var imagesState = useState([]);
  var images = imagesState[0];
  var setImages = imagesState[1];

  var loadingState = useState(false);
  var loading = loadingState[0];
  var setLoading = loadingState[1];

  var pageState = useState(1);
  var page = pageState[0];
  var setPage = pageState[1];

  var totalState = useState(0);
  var total = totalState[0];
  var setTotal = totalState[1];

  var selectedState = useState(null);
  var selected = selectedState[0];
  var setSelected = selectedState[1];

  var errorState = useState('');
  var error = errorState[0];
  var setError = errorState[1];

  var loadingRef = useRef(false);
  var sentinelRef = useRef(null);
  var currentQueryRef = useRef('');
  var currentPageRef = useRef(1);
  var totalRef = useRef(0);
  var imagesLenRef = useRef(0);

  var search = function(q, pg) {
    var qq = q !== undefined ? q : query;
    var p = pg !== undefined ? pg : 1;
    if (!qq.trim()) return;
    if (loadingRef.current) return;
    loadingRef.current = true;
    setLoading(true);
    setError('');
    axios.get('https://api.pexels.com/v1/search', {
      headers: { Authorization: PEXELS_KEY },
      //
    }).then(function(res) {
      var data = res.data;
      if (p === 1) {
        setImages(data.photos);
        imagesLenRef.current = data.photos.length;
      } else {
        setImages(function(prev) {
          var next = prev.concat(data.photos);
          imagesLenRef.current = next.length;
          return next;
        });
      }
      setTotal(data.total_results);
      totalRef.current = data.total_results;
      setPage(p);
      currentPageRef.current = p;
    }).catch(function() {
      setError('Failed to load images. Try again.');
    }).finally(function() {
      setLoading(false);
      loadingRef.current = false;
    });
  };

  var handleNewSearch = function(q) {
    currentQueryRef.current = q;
    currentPageRef.current = 1;
    imagesLenRef.current = 0;
    totalRef.current = 0;
    setImages([]);
    setPage(1);
    setTotal(0);
    search(q, 1);
  };

  useEffect(function() {
    var sentinel = sentinelRef.current;
    if (!sentinel) return;
    var observer = new IntersectionObserver(function(entries) {
      var entry = entries[0];
      if (
        entry.isIntersecting &&
        !loadingRef.current &&
        imagesLenRef.current > 0 &&
        imagesLenRef.current < totalRef.current
      ) {
        search(currentQueryRef.current, currentPageRef.current + 1);
      }
    }, { rootMargin: '500px' });
    observer.observe(sentinel);
    return function() { observer.disconnect(); };
  }, []);

  return React.createElement(
    'div',
    { style: { background: '#fff', minHeight: '100vh' } },
    React.createElement('style', null, imageSearchCSS),

    React.createElement(
      'div',
      { style: is.header },
      React.createElement(
        'div',
        { className: 'container' },
        React.createElement('h1', { style: is.title }, 'Inkwell Images'),
        React.createElement('p', { style: is.sub }, 'Discover, search, and save high-quality visuals effortlessly'),
        React.createElement(
          'div',
          { style: is.searchBar },
          React.createElement(
            'svg',
            { width: 20, height: 20, viewBox: '0 0 24 24', fill: 'none', stroke: '#9b9b9b', strokeWidth: 2 },
            React.createElement('circle', { cx: 11, cy: 11, r: 8 }),
            React.createElement('path', { d: 'm21 21-4.35-4.35' })
          ),
          React.createElement('input', {
            style: is.searchInput,
            placeholder: 'Search for photos...',
            value: query,
            onChange: function(e) { setQuery(e.target.value); },
            onKeyDown: function(e) { if (e.key === 'Enter') handleNewSearch(query); },
          }),
          React.createElement(
            'button',
            { style: is.searchBtn, onClick: function() { handleNewSearch(query); } },
            'Search'
          )
        ),
        React.createElement(
          'div',
          { style: is.chips },
          SUGGESTIONS.map(function(s) {
            return React.createElement(
              'button',
              {
                key: s,
                style: is.chip,
                onClick: function() {
                  setQuery(s);
                  setTimeout(function() { handleNewSearch(s); }, 50);
                },
              },
              s
            );
          })
        )
      )
    ),

    React.createElement(
      'div',
      { className: 'container', style: { paddingBottom: 60 } },
      error ? React.createElement('div', { style: is.error }, error) : null,

      !loading && images.length === 0
        ? React.createElement(
            'div',
            { style: is.empty },
            React.createElement('div', { style: { fontSize: 64, marginBottom: 16 } }, '\uD83D\uDD0D'),
            React.createElement('h3', { style: { fontFamily: 'Lora, serif', fontSize: 22, marginBottom: 8 } }, 'Explore beautiful photos'),
            React.createElement('p', { style: { color: '#9b9b9b', fontSize: 15 } }, 'Search for any topic above to get started.')
          )
        : null,

      images.length > 0
        ? React.createElement(
            'div',
            null,
            React.createElement(
              'div',
              { style: { fontSize: 13, color: '#9b9b9b', margin: '24px 0 16px' } },
              total.toLocaleString() + ' results for "' + currentQueryRef.current + '"'
            ),
            React.createElement(
              'div',
              { style: is.masonryGrid, className: 'masonry-grid' },
              images.map(function(img, idx) {
                return React.createElement(PinCard, { key: img.id + '-' + idx, img: img, onSelect: setSelected });
              }),
              loading
                ? Array.from({ length: 6 }).map(function(_, i) {
                    return React.createElement('div', { key: 'sk' + i, className: 'pin-skeleton' });
                  })
                : null
            ),
            React.createElement('div', { ref: sentinelRef, style: { height: 1 } }),
            loading && images.length > 0
              ? React.createElement(
                  'div',
                  { style: { textAlign: 'center', padding: '24px 0' } },
                  React.createElement('div', { className: 'pin-spinner' })
                )
              : null,
            !loading && images.length >= total && total > 0
              ? React.createElement(
                  'div',
                  { style: { textAlign: 'center', padding: '32px 0', fontSize: 13, color: '#9b9b9b' } },
                  'All ' + total.toLocaleString() + ' images loaded'
                )
              : null
          )
        : null
    ),

    selected
      ? React.createElement(
          'div',
          { style: is.lightbox, onClick: function() { setSelected(null); } },
          React.createElement(
            'div',
            { style: is.lightboxBox, onClick: function(e) { e.stopPropagation(); } },
            React.createElement('button', { style: is.closeBtn, onClick: function() { setSelected(null); } }, '\u2715'),
            React.createElement('img', { src: selected.src.large, alt: selected.alt, style: is.lightboxImg }),
            React.createElement(
